def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    negative_integers = [i for i in lst if i < 0]
    positive_integers = [i for i in lst if i > 0]

    if negative_integers and not positive_integers:
        return (min(negative_integers), None)
    elif not negative_integers and positive_integers:
        return (None, min(positive_integers))
    elif negative_integers and positive_integers:
        return (min(negative_integers), min(positive_integers))
    else:
        return (None, None)
```

