def eulerian_num(n, m):
    if n == m:
        return 1
    if n < m:
        return 0
    a = [0] * (n + 1)
    a[0] = a[1] = 1
    for i in range(2, n + 1):
        for j in range(1, i):
            a[i] += j * a[i - j]
    return a[n]
