def pancake_sort(lst):
    n = len(lst)
    for size in range(n, 0, -1):
        min_idx = lst.index(min(lst[:size]))
        if min_idx != size - 1:
            if min_idx != 0:
                lst[:min_idx + 1] = lst[:min_idx + 1][::-1]
            lst[:size] = lst[:size][::-1]
    return lst
```

