def min_Swaps(s1, s2):
    if s1 == s2:
        return 0
    if s1[0] != s2[0] or s1[-1] != s2[-1]:
        return "Not Possible"
    n = len(s1)
    swaps = 0
    i = 0
    while i < n - 1:
        if s1[i] != s2[i]:
            j = i + 1
            while s1[j] != s2[i]:
                j += 1
            if j == n:
                return "Not Possible"
            s1 = s1[:i] + s1[j] + s1[i+1:j] + s1[i+1:j]
            swaps += 1
        i += 1
    return swaps
```

