def pancake_sort(arr):
    n = len(arr)
    for i in range(n, 0, -1):
        max_index = arr.index(max(arr[:i]))
        if max_index == i - 1:
            continue
        if max_index == 0:
            arr = arr[::-1]
            arr[0:i] = arr[0:i][::-1]
        else:
            arr[:max_index + 1] = arr[:max_index + 1][::-1]
            arr[:i] = arr[:i][::-1]
    return arr
```

