def min_Swaps(s1, s2):
    if len(s1) != len(s2):
        return "Not Possible"
    if s1 == s2:
        return 0
    count = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            if s1[i] == s2[len(s2) - i - 1]:
                count += 1
            elif s2[i] == s1[len(s1) - i - 1]:
                count += 1
            else:
                return "Not Possible"
    if count % 2 == 0:
        return count // 2
    else:
        return "Not Possible"
```

