def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - 97 + 2) % 26 + 97) for v in vowels}
    shifted_vowels.update({v.upper(): chr((ord(v.upper()) - 65 + 2) % 26 + 65) for v in vowels})

    def swap_case_and_shift_vowel(char):
        if char.isalpha():
            if char in shifted_vowels:
                return shifted_vowels[char]
            else:
                return char.swapcase()
        else:
            return char

    return ''.join(swap_case_and_shift_vowel(char) for char in message)
```

