from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    def dfs(x, y, path, visited, total):
        if total == k:
            return path
        if total > k:
            return None

        visited[x][y] = True
        for dx, dy in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and not visited[nx][ny]:
                path.append(grid[nx][ny])
                result = dfs(nx, ny, path, visited, total + 1)
                if result:
                    return result
                path.pop()

        visited[x][y] = False
        return None

    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    result = dfs(0, 0, [grid[0][0]], visited, 1)
    if result:
        return result

    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            result = dfs(i, j, [grid[i][j]], visited, k)
            if result:
                return result

    return []
```

