def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    if n % 2 != 0:
        return False

    candidates = set(range(2, n+1, 2))
    if len(candidates) < 4:
        return False

    candidates_copy = candidates.copy()
    while len(candidates) > 4:
        for candidate in candidates:
            for other in candidates_copy:
                if candidate + other > n:
                    break
                if candidate + other in candidates:
                    candidates.remove(candidate)
                    candidates.remove(other)
                    break
        else:
            candidates_copy.remove(min(candidates))

    return n in candidates and all(c1 + c2 + c3 + c4 == n for c1, c2, c3, c4 in itertools.combinations(candidates, 4))
