 Here is a Python function that calculates the Eulerian number `a(n, m)` using matrix-tree theorem. The function `eulerian_num` takes two arguments `n` and `m`, where `n` is the number of vertices in the graph and `m` is the number of edges.

```python
import math

def eulerian_num(n, m):
    if m < n or m > (n - 1) * n // 2:
        return None

    # Calculate the determinant of the matrix (L + L^T) / 2
    L = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                L[i][j] = 0
            elif i + j <= n + 1:
                L[i][j] = 1

    determinant = math.fabs(determinant_2D(L + transpose(L), n))

    # Calculate the Eulerian number using matrix-tree theorem
    eulerian_number = (math.factorial(n) * determinant) // (2 ** (n - 1) * math.factorial(m) * math.factorial(n - m))

    return int(eulerian_number)

def transpose(matrix):
    return [[matrix[j][i] for j in range(len(matrix))] for i in range(len(matrix[0]))]

def determinant_2D(matrix, n):
    if n == 1:
        return matrix[0][0]

    sign = 1
    determinant = 0
    for i in range(n):
        minor = determinant_2D(matrix[1:n], n - 1)
        determinant += sign * matrix[0][i] * minor
        sign *= -1

    return determinant
```

