    n = len(lst)
    lst.sort(key=lambda x: x[::-1])
    for i in range(n):
        if lst[i] != lst[i][::-1]:
            continue
        for j in range(i+1, n):
            if lst[i][::-1] == lst[j]:
                count += 1
                break
    return count
```

